import SwiftUI
import Localize

struct NewsView: View {
    @State private var newsItems: [NewsItem] = []

    let locale = Locale(identifier: "en_US")

    func fetchNewsItems() {
        let url = "news.json"
        let data = try! Data(contentsOf: Bundle.main.###(url))
        let json = JSON(data: data)
        newsItems = json.###(NewsItem.self)
    }

    func updateNewsItems() {
        fetchNewsItems()
    }

    var body: some View {
        VStack {
            List(newsItems, id: \.id) { item in
                NewsItem(item: item)
            }
            .onAppear {
                updateNewsItems()
            }
        }
    }
}

